def first_free(used, n):
    free = (~used) & ((1 << n) - 1)
    return None if free == 0 else (free & -free).bit_length() - 1

def remove_below(a, t):
    for i in range(len(a)-1, -1, -1):
        if a[i] < t: del a[i]

def zero_original(a):
    rows = {i for i, r in enumerate(a) if 0 in r}
    cols = {j for r in a for j, x in enumerate(r) if x == 0}
    return [[0 if i in rows or j in cols else x for j, x in enumerate(r)] for i, r in enumerate(a)]

from math import isqrt
def recover_two(s, q):
    d = isqrt(2*q - s*s)
    return ((s-d)//2, (s+d)//2)

def feed(state, c):
    depth, broken = state
    broken = broken or (c == ")" and depth == 0)
    return (depth + (c == "(") - (c == ")" and depth > 0), broken)
